-- Suppliers (fuente: Desktop/DOCS MBG/MBG.xlsx, tabs Vendor Company+Vendor Contact)


-- Freight Carriers (entidad nueva, ver documento Trading OS sección 3.8)
create table freight_carriers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  country text,
  city text,
  contact_name text,
  email text,
  phone text,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table freight_carriers enable row level security;
create policy "authenticated_full_access_freight_carriers"
on freight_carriers for all to authenticated using (true) with check (true);
grant select, insert, update, delete on freight_carriers to authenticated;

